/**
 * Film ⇄ backend reproducibility (npm run test:film-backend).
 *
 * Nobody's Witness is generated by tools/build-film-story.mjs, but it is an ordinary Story on the Scarlet Reel engine. Everything it
 * uses must be something the Studio can author, the media pipeline can resolve and export, and the validator understands, or a
 * film feature exists that nobody can reproduce, move or export from the backend. This checks:
 *   1. the film validates (no errors, and no false ambience warnings);
 *   2. every field the film uses on a node, beat, camera, light, credits card, character or the story has a Studio control (a
 *      registry below: a new film feature with no control fails here);
 *   3. the media walker sees every file the film references (so uploads resolve and exports bundle them) — beat sound effects and
 *      recorded ambience loops included;
 *   4. the whole film survives being moved onto library assets (`asset:<id>`) and back unchanged;
 *   5. the ambience editor reads and writes every ambience string the film has;
 *   6. the engine reads what the Studio writes (particleConfig, musicLoop, animaticReadPace, montageLooks, depth fields).
 */
import assert from "node:assert/strict";
import { readFileSync, readdirSync, existsSync } from "node:fs";
import { join } from "node:path";
import { NOBODYS_WITNESS_FILM as FILM } from "../src/data/nobodysWitnessFilm";
import { validateStory, deepClone, latestSave, writeSave } from "../src/logic";
import { creditsRollSeconds } from "../src/credits";
import { visitStoryMediaFields } from "../src/data/storyMedia";
import { collectStoryAssetIds, resolveMediaValue } from "../src/data/mediaLibrary";
import { parseAmbient, joinAmbient } from "../src/studio/ambientParts";
import { countExportFiles, LARGE_EXPORT_FILES } from "../src/studio/exportBundle";
import { scanBuiltinImages, labelFor } from "../tools/builtin-images.mjs";
import { scanBuiltinAudio, sectionFor } from "../tools/builtin-audio.mjs";

let checks = 0;
const check = (value: unknown, message: string) => { assert.ok(value, message); checks++; };
const eq = (a: unknown, b: unknown, message: string) => { assert.deepEqual(a, b, message); checks++; };
const ROOT = process.cwd();
const read = (p: string) => readFileSync(join(ROOT, p), "utf8");
const studioSrc = readdirSync(join(ROOT, "src/studio")).filter((f) => /\.tsx?$/.test(f)).map((f) => read(`src/studio/${f}`)).join("\n");

/* ---- 1. the film validates ---- */
console.log("The film validates");
const issues = validateStory(FILM);
eq(issues.filter((i) => i.severity === "error").map((i) => i.message), [], "no validation errors");
eq(issues.filter((i) => /ambient loop/.test(i.message)).length, 0, "no false 'not a known synth loop' warnings for recorded ambience");

/* ---- 2. every field the film uses has a Studio control ---- */
console.log("Every field the film uses can be authored in the Studio");
// field -> a pattern that appears in the Studio source only where that field is written. `null` = set by the Studio's own plumbing
// (ids, layout) rather than a control.
const REGISTRY: Record<string, Record<string, RegExp | null>> = {
  story: {
    id: null, builtinRevision: null, title: /Story title/, tagline: /tagline/, pulpPaper: /pulpPaper/, gameKind: /gameKind/, coverImage: /coverImage/,
    startSceneId: /startSceneId/, layout: /layout/, dialogueBox: /dialogueBox/, briefing: /briefing/, characters: /characters/, items: /items/, scenes: /scenes/,
  },
  scene: {
    id: null, title: /title:/, background: /background/, prose: /prose/, dialogueBeats: /dialogueBeats/, hotspots: /hotspots/, choices: /choices/,
    noTypewriter: /noTypewriter/, autoNarrate: /autoNarrate/, transition: /transition/, transitionSpeed: /transitionSpeed/,
    ambientAudio: /AmbientLayers/, hideHud: /hideHud/, particles: /Particle Effects/, particleConfig: /aria-label=\{`Particle \$\{label/,
    cinematic: /CinematicControls/, musicMode: /musicMode/, musicFadeSeconds: /musicFadeSeconds/, animaticReadPace: /Animatic reading pace/,
    musicUrl: /musicUrl/, musicLevel: /musicLevel/, musicLoop: /Loop this track/, nodeType: /nodeType/, credits: /credits/,
    autoAdvanceTargetSceneId: /autoAdvanceTargetSceneId/, autoAdvanceDelaySeconds: /autoAdvanceDelaySeconds/, autoAdvanceHideTimer: /autoAdvanceHideTimer/,
    isEnding: /isEnding/, endingData: /endingData/,
  },
  beat: {
    id: null, characterId: /characterId/, text: /Line for beat/, silent: /silent/, audioUrl: /audioUrl/, background: /background/, cinematic: /CinematicControls/,
    backgroundTransition: /backgroundTransition/, backgroundTransitionSpeed: /backgroundTransitionSpeed/, sfxUrl: /Sound effect for beat/, sfxVolume: /Sound effect volume for beat/,
    afterBeatTargetSceneId: /afterBeatTargetSceneId/, afterBeatMode: /afterBeatMode/, afterBeatDelaySeconds: /afterBeatDelaySeconds/, expression: /expression/, backgroundRevert: /backgroundRevert/,
  },
  cinematic: {
    mode: /Camera mode/, focalPoint: /focalPoint/, zoomDuration: /zoomDuration/, panDirection: /panDirection/, panDistance: /panDistance/, colorGrade: /colorGrade/,
    filmGrade: /filmGrade/, filmGradeStrength: /filmGradeStrength/, dollyDirection: /dollyDirection/, dollyDistance: /dollyDistance/, dollyDuration: /dollyDuration/,
    shakeAmount: /shakeAmount/, shakeDuration: /shakeDuration/, lights: /lights/, depthMap: /depthMap/, depthMotion: /depthMotion/, depthAmount: /depthAmount/,
    depthSeconds: /depthSeconds/, depthPlate: /depthPlate/, depthCutouts: /depthCutouts/, depthDirection: /depthDirection/, depthFocus: /depthFocus/,
    volumetricShafts: /volumetricShafts/, shaftsIntensity: /shaftsIntensity/, lensFlare: /lensFlare/, dimAmount: /dimAmount/, rainOnLens: /rainOnLens/,
    rainLensIntensity: /rainLensIntensity/, dollyZoomAmount: /dollyZoomAmount/, dollyZoomDuration: /dollyZoomDuration/, dollyZoomDirection: /dollyZoomDirection/,
  },
  light: { x: /\bx:/, y: /\by:/, color: /color/, size: /size/, intensity: /intensity/, pulseSeconds: /pulseSeconds/, pulseAmount: /pulseAmount/ },
  credits: {
    title: /title/, subtitle: /subtitle/, lines: /lines/, style: /style/, cardSeconds: /cardSeconds/, montage: /montage/, montageSeconds: /montageSeconds/,
    montageTransition: /montageTransition/, montageLoop: /montageLoop/, gateWeave: /gateWeave/, font: /font/, cardMotion: /cardMotion/, titleColor: /titleColor/,
    accentColor: /accentColor/, titleEntrance: /titleEntrance/, montageLooks: /Camera look per still/, stagger: /stagger/, duration: /duration/, scrollDuration: /scrollDuration/,
  },
  character: { id: null, name: /name/, role: /role/, avatarUrl: /avatarUrl/, trustMeter: /trustMeter/ },
};
const used = { story: new Set<string>(), scene: new Set<string>(), beat: new Set<string>(), cinematic: new Set<string>(), light: new Set<string>(), credits: new Set<string>(), character: new Set<string>() };
Object.keys(FILM).forEach((k) => used.story.add(k));
FILM.characters.forEach((c) => Object.keys(c).forEach((k) => used.character.add(k)));
const eachCinematic = (c: Record<string, unknown> | undefined) => { if (!c) return; Object.keys(c).forEach((k) => used.cinematic.add(k)); (c.lights as Record<string, unknown>[] | undefined)?.forEach((l) => Object.keys(l).forEach((k) => used.light.add(k))); };
for (const s of FILM.scenes) {
  Object.keys(s).forEach((k) => used.scene.add(k));
  eachCinematic(s.cinematic as never);
  Object.keys(s.credits ?? {}).forEach((k) => used.credits.add(k));
  for (const b of s.dialogueBeats ?? []) { Object.keys(b).forEach((k) => used.beat.add(k)); eachCinematic(b.cinematic as never); }
}
for (const kind of Object.keys(used) as (keyof typeof used)[]) {
  const missing = [...used[kind]].filter((f) => !(f in REGISTRY[kind]));
  eq(missing, [], `the film's ${kind} fields are all in the registry (add a Studio control, then the registry, for: ${missing.join(", ")})`);
  const uncontrolled = [...used[kind]].filter((f) => REGISTRY[kind][f] instanceof RegExp && !(REGISTRY[kind][f] as RegExp).test(studioSrc));
  eq(uncontrolled, [], `every ${kind} field the film uses has a Studio control (none found for: ${uncontrolled.join(", ")})`);
}

/* ---- 3. the media walker sees every file the film references ---- */
console.log("The media walker sees every file the film references");
const json = JSON.stringify(FILM);
const referenced = new Set<string>();
for (const m of json.matchAll(/"(\/film\/[^"]+\.(?:mp3|jpg|jpeg|png|webp|mp4|wav|ogg))"/g)) referenced.add(m[1]);
for (const m of json.matchAll(/file:(\/film\/[^"+]+\.(?:mp3|wav|ogg))/g)) referenced.add(m[1]);
const seen = new Set<string>();
visitStoryMediaFields(deepClone(FILM), ({ value }) => seen.add(value));
const unseen = [...referenced].filter((v) => !seen.has(v));
eq(unseen, [], `the media walker visits all ${referenced.size} files the film references (missed: ${unseen.slice(0, 4).join(", ")}${unseen.length > 4 ? "…" : ""})`);
check(referenced.size > 1000, "and the film really does reference more than a thousand files");
// the credits montage's camera looks carry depth maps of their own (80-the-machine-waits has been in the montage only since the
// director's picks for Vera's run, 19 October 2026, so nothing else reaches its map)
const montageDepth = FILM.scenes.flatMap((s) => Object.values(s.credits?.montageLooks ?? {}))
  .flatMap((c) => [c.depthMap, c.depthPlate, ...(c.depthCutouts ?? []).map((k) => k.image)]).filter((v): v is string => !!v);
check(montageDepth.length > 0 && montageDepth.every((v) => seen.has(v)), `the credits montage's depth maps are media fields (${montageDepth.length} files)`);
const sfx = [...referenced].filter((v) => v.startsWith("/film/sfx/"));
check(sfx.length > 100 && sfx.every((v) => seen.has(v)), `beat sound effects and recorded ambience loops are media fields (${sfx.length} files)`);
const onDisk = [...referenced].filter((v) => existsSync(join(ROOT, "public", v)));
eq([...referenced].filter((v) => !onDisk.includes(v)), [], "and every one of them is on disk under public/");

/* ---- 4. the film survives moving onto library assets and back ---- */
console.log("The film survives moving onto library assets and back");
const moved = deepClone(FILM);
const library: Record<string, string> = {};
let n = 0;
visitStoryMediaFields(moved, ({ value, set }) => { const id = `t${++n}`; library[id] = value; set(`asset:${id}`); });
const ids = collectStoryAssetIds(moved);
eq(ids.size, n, "every media reference becomes one library asset id, including recorded ambience loops and sound effects");
check(!JSON.stringify(moved).includes("/film/sfx/"), "no sound-effect or ambience file path is left outside the library");
visitStoryMediaFields(moved, ({ value, set }) => set(resolveMediaValue(value, library) ?? value));
eq(moved, FILM, "resolving them again gives back the film exactly");

/* ---- 5. the ambience editor reads and writes every ambience string the film has ---- */
console.log("The ambience editor reads and writes every ambience string the film has");
const ambients = new Set(FILM.scenes.map((s) => s.ambientAudio).filter(Boolean) as string[]);
check(ambients.size > 20, `${ambients.size} different ambience strings`);
const odd = [...ambients].filter((a) => { const p = parseAmbient(a); return joinAmbient(p.preset, p.loops, p.other) !== a; });
eq(odd, [], "parse then join returns every film ambience unchanged");

/* ---- 6. the engine reads what the Studio writes ---- */
console.log("The engine reads what the Studio writes");
const particles = read("src/game/AmbientParticles.tsx");
check(/config\?\.density/.test(particles) && /config\?\.opacity/.test(particles) && /config\?\.wind/.test(particles), "particleConfig density, opacity and wind are applied by the renderer");
check(/config=\{scene\.particleConfig\}/.test(read("src/game/Game.tsx")), "and the player hands the scene's particleConfig to it");
check(/scene\.musicLoop !== false/.test(read("src/game/Game.tsx")), "musicLoop: false makes a track play once");
check(/animaticReadPace/.test(read("src/game/Game.tsx")) && /animaticReadPace/.test(read("tools/export-animatic.mjs")), "animaticReadPace is read by the player and the exporter");
check(/looks\?\.\[img\]/.test(read("src/game/Game.tsx")), "montageLooks are looked up per still");
check(/sfxUrl/.test(read("src/game/Game.tsx")) && /audio\.playSfx\(currentBeat\.sfxUrl/.test(read("src/game/Game.tsx")), "a beat's sfxUrl is played when the beat starts");
check(!/particleConfig/.test(read("tools/build-film-story.mjs").replace(/const LOOK = [^\n]+/g, "")), "the film builder no longer sets a particleConfig the engine ignored (the film keeps the look it was approved with)");

/* ---- 7. the film's music cues point at real files, and scene 4's radio stops with the scene ---- */
console.log("The film's music cues point at real files");
const tracks = FILM.scenes.filter((s) => s.musicMode === "track" && s.musicUrl);
const missingTracks = [...new Set(tracks.map((s) => s.musicUrl as string))].filter((u) => !existsSync(join(ROOT, "public", u.replace(/^\/film\//, "film/"))));
eq(missingTracks, [], `all ${new Set(tracks.map((s) => s.musicUrl)).size} soundtrack files exist`);
const at = (id: string) => FILM.scenes.find((s) => s.id === id);
check(at("nw_s4")?.musicUrl === "/film/audio/it-aint-easy-wall.mp3" && (at("nw_s4")?.musicLevel ?? 1) <= 0.5, "scene 4: the neighbour's radio plays quietly through the wall");
check(at("nw_s4")?.musicLoop === false, "and plays once");
check(at("nw_s5")?.musicMode === "none", "scene 5 ends it (the door has closed on the song)");
check(at("nw_s35")?.musicUrl === "/film/audio/you-never-call.mp3" && at("nw_s35")?.musicLoop === false && (at("nw_s35")?.musicLevel ?? 1) <= 0.6, "scene 35: You Never Call starts once at the pink payphone, under the picture");
check(!at("nw_s36")?.musicMode && !at("nw_s37")?.musicMode, "scenes 36 and 37 keep it running (the call, the keys in the car)");
check(at("nw_s38")?.musicMode === "none" && (at("nw_s38")?.musicFadeSeconds ?? 9) <= 0.5, "the four black sedans cut it dead");
const lullabyLevel = FILM.scenes.find((s) => s.musicUrl === "/film/audio/Maras Lullaby.mp3")?.musicLevel ?? 1;
check(lullabyLevel >= 0.45 && lullabyLevel <= 0.6, `Mara's lullaby sits at ${lullabyLevel} (it was too quiet at 0.35)`);
const riceBeat = FILM.scenes.filter((s) => s.id.startsWith("nw_s25")).flatMap((s) => s.dialogueBeats ?? []).find((b) => b.text?.startsWith("The rice goes cold"));
check(riceBeat?.background === "/film/img/s25/the-rice-goes-cold.jpg" && existsSync(join(ROOT, "public/film/img/s25/the-rice-goes-cold.jpg")), "scene 25: Jack and Mara at \"The rice goes cold\" have their own picture");

/* ---- 8. the Studio helps with what the film uses ---- */
console.log("The Studio helps with what the film uses");
const small = { ...FILM, scenes: FILM.scenes.slice(0, 3) };
check(countExportFiles(FILM) >= LARGE_EXPORT_FILES, `the whole film (${countExportFiles(FILM)} files) is above the size at which the Studio asks before exporting`);
check(countExportFiles(small) < LARGE_EXPORT_FILES, `three of its scenes (${countExportFiles(small)} files) export without asking`);
check(countExportFiles({ ...FILM, scenes: [] }) < 40, `a story with no scenes has only its cover, avatars and the like (${countExportFiles({ ...FILM, scenes: [] })} files)`);
// The image browser's list is scanned from disk by tools/builtin-images.mjs.
// Every picture, plate and depth map the film uses must be IN it — otherwise
// the film's own art is not something the Studio can re-pick.
const BUILTINS = scanBuiltinImages(ROOT);
const pickerUrls = new Set(BUILTINS.map((b) => b.url));
const pictureUrls = new Set(BUILTINS.filter((b) => b.group === "film-img").map((b) => b.url));
const layerUrls = new Set(BUILTINS.filter((b) => b.group === "film-depth").map((b) => b.url));

const filmRefs = new Set<string>();
visitStoryMediaFields(deepClone(FILM), ({ value }) => { if (value) filmRefs.add(value); });
const filmPictures = [...filmRefs].filter((v) => v.startsWith("/film/img/"));
const filmLayers = [...filmRefs].filter((v) => v.startsWith("/film/depth/"));
check(filmPictures.length > 200, `the film references ${filmPictures.length} of its own pictures`);
eq(filmPictures.filter((u) => !pictureUrls.has(u)), [], "every picture the film uses is in the image browser (group film-img)");
eq(filmLayers.filter((u) => !layerUrls.has(u)), [], `every one of its ${filmLayers.length} depth maps, plates and cut-outs is there too (group film-depth)`);
check(pickerUrls.size === BUILTINS.length && BUILTINS.length > 800, `the browser offers all ${BUILTINS.length} images the scan finds`);
check(labelFor("s1/377-the-hive-remembered.jpg") === "377 The Hive Remembered (s1)", "pictures are labelled by scene and shot");
check(labelFor("s1/377-the-hive-remembered/depth.png") === "377 The Hive Remembered — depth (s1)", "depth layers are labelled by the shot they belong to");
check(/groups\?\.includes\(b\.group\)/.test(read("src/studio/ImagePicker.tsx")) && /autoGroups\.includes\(b\.group\)/.test(read("src/studio/ImagePicker.tsx")),
  "and only the pickers that ask for a group — or already point into one — show it");
check((read("src/studio/CinematicControls.tsx").match(/groups=\{FILM_DEPTH\}/g) ?? []).length === 3, "the depth map, clean plate and cut-out pickers ask for the depth layers");
const depthFiles = readdirSync(join(ROOT, "public/film/depth"), { recursive: true }).filter((f) => /depth\.png$/.test(String(f)));
check(depthFiles.length > 40, `${depthFiles.length} depth maps are on offer`);

/* ---- 9. the player never lets the scene's own picture show through a beat's ---- */
console.log("The player holds the picture before until the next one has loaded");
const game = read("src/game/Game.tsx");
check(/pictureReady\(url\)/.test(game) && /preloadPicture\(url\)\.then\(mount\)/.test(game), "a beat's picture is mounted only once it is decoded (the one before it stays up until then)");
check(/preloadPicture\(url\)/.test(game) && /visibleBeats\.slice\(beatIdx, beatIdx \+ 5\)/.test(game), "and the next beats' pictures, and the next node's, are fetched while the player reads");
check(existsSync(join(ROOT, "src/game/preloadPicture.ts")), "preloadPicture.ts holds the preloading");

/* ---- 8b. every sound the film uses is in the sound browser ---- */
// The beat's "sound effect on this beat" box and the scene's recorded-loop
// adder both browse the scan in tools/builtin-audio.mjs. If a sound the film
// plays were missing from it, the sound could only be set by typing a path —
// which is exactly what the browser replaced.
console.log("Every sound the film uses is in the sound browser");
const SOUNDS = scanBuiltinAudio(ROOT);
const soundUrls = new Set(SOUNDS.map((a) => a.url));
const filmSounds = [...filmRefs].filter((v) => v.startsWith("/film/sfx/") || v.startsWith("/film/audio/"));
check(filmSounds.length > 100, `the film references ${filmSounds.length} sound files (one-shots, ambience loops, music cues)`);
eq(filmSounds.filter((u) => !soundUrls.has(u)), [], "and every one of them is in the sound browser");
check(SOUNDS.length > 1000, `the browser offers all ${SOUNDS.length} sounds the scan finds under public/`);
check(sectionFor("film/sfx").name === "Film one-shots & ambience (film/sfx)" && sectionFor("film/sfx").rank === 1, "the film's own one-shots and ambience lead the list, right after your uploads");
check(sectionFor("film/sfx/alternates").name === "Alternate takes (film/sfx/alternates)", "alternate takes are kept apart from the finals");
check(sectionFor("film/audio").name === "Film music cues (film/audio)", "music cues are named for what they are");
check(sectionFor("reels/rapture/audio").name === "Other reels (reels)", "the other reels' audio is kept out of the film's way");
check(sectionFor("uploads/nobody-draft").name === "Already in public/uploads", "imported uploads are named for what they are");
check(/<AudioPicker/.test(read("src/studio/Studio.tsx")), "the beat's sound-effect field uses the sound browser");
check(/<AudioPicker/.test(read("src/studio/AmbientLayers.tsx")), "and so does the scene's recorded-loop adder");
check(/onMouseEnter=\{\(\) => audition/.test(read("src/studio/AudioPicker.tsx")) && /<audio ref=\{audioRef\}/.test(read("src/studio/AudioPicker.tsx")), "pointing at a sound auditions it through one shared player");
check((read("src/studio/AmbientLayers.tsx").match(/<MediaUploadButton/g) ?? []).length === 1, "and the ambient field keeps its own upload button");

/* ---- 10. the film grade's flicker never fades the plate ---- */
console.log("The 35mm film grade flickers a veil, never the picture");
const css = read("src/index.css");
const rule = (sel: string) => (css.match(new RegExp(`(^|\\n)${sel.replace(/[.>]/g, "\\$&")} \\{([^}]*)\\}`)) ?? [])[2] ?? "";
const gradeRule = rule(".film-grade");
check(/film-gate-weave/.test(gradeRule) && !/film-flicker/.test(gradeRule) && !/opacity/.test(gradeRule), "the film-graded plate weaves but is never faded (its opacity once flickered over whatever was beneath it)");
check(/film-flicker/.test(rule(".film-grade > .film-flicker")) && /background:\s*#000/.test(rule(".film-flicker")), "the exposure flicker is a black veil above the plate");
check(/<div className="film-flicker"/.test(game), "CinematicOverlays renders the veil with the scratches");

/* ---- 11. a depth map's default move is a truck ---- */
console.log("A depth map with no move set trucks");
check(/cinematic\?\.depthMotion \?\? "truck"/.test(read("src/game/DepthParallax.tsx")), "the engine's default move is a truck");
const controls = read("src/studio/CinematicControls.tsx");
check(/depthMotion: c\.depthMotion \?\? "truck"/.test(controls) && /value=\{c\.depthMotion \?\? "truck"\}/.test(controls), "the Studio starts a new map on a truck and shows it as the Move");
check(!/depthMotion[^\n]*\?\? "push"/.test(controls + read("src/game/DepthParallax.tsx")), "nothing still falls back to a push");

/* ---- 12. Jack's breath effects at the inn are few ---- */
console.log("Jack's breath effects in the inn raid are few");
const edits = JSON.parse(read("src/film/studio-edits.json"));
const raid = edits.cutscenes.find((c: { id: string }) => c.id === "inn-raid");
const jackBreaths = raid.shots.filter((shot: { sfx?: string }) => /^jack-(running|grunt|shaky-breath|sigh)/.test(shot.sfx ?? ""));
check(raid.songRunsOn === true && FILM.scenes.find((s) => s.musicUrl === "/film/audio/hounds.mp3")?.musicLoop === false, "Hounds plays once and runs on after the raid (songRunsOn)");
check(FILM.scenes.find((s) => s.id === "nw_s50")?.musicMode === undefined && FILM.scenes.find((s) => s.id === "nw_s51")?.musicMode === undefined, "scenes 50 and 51 let it play to its end");
check(FILM.scenes.find((s) => s.id === "nw_s52")?.musicUrl === "/film/audio/dark-hills-blues.mp3", "Vera's apartment (52) takes over with Dark Hills Blues");
check(jackBreaths.length <= 1, `the inn raid carries at most one breath or grunt effect on Jack (the director found too many; it has ${jackBreaths.length})`);

/* ---- 13. the film opens on scenes 1 and 2, then the titles (this regressed twice: a stale Studio copy, then the export dialog) ---- */
console.log("The film opens on scene 1 and 2, then the opening titles");
const byId = new Map(FILM.scenes.map((s) => [s.id, s]));
const nextOf = (id: string) => { const sc = byId.get(id)!; const beats = sc.dialogueBeats ?? []; return beats[beats.length - 1]?.afterBeatTargetSceneId || sc.autoAdvanceTargetSceneId || sc.choices?.[0]?.targetSceneId; };
const order: string[] = [];
for (let id: string | undefined = FILM.startSceneId; id && byId.has(id) && !order.includes(id); id = nextOf(id)) order.push(id);
eq(order.slice(0, 5), ["nw_s1", "nw_s2", "nw_title", "nw_prologue", "nw_s3"], "the film starts on scene 1, then scene 2, the opening titles, the prologue and scene 3");
check(order.length > 100, `and plays on through the whole film (${order.length} nodes in play order)`);
check(typeof FILM.builtinRevision === "string" && FILM.builtinRevision.length >= 8, "each build of the film is stamped, so a saved Studio copy from an older build can be told from it");
const appSrc = read("src/App.tsx");
check(/saved\.builtinRevision !== revision/.test(appSrc) && /data-testid="stale-copy-notice"/.test(appSrc), "the newsstand says so when a saved copy of the film is from an older build, and offers the current film");
check(/STORIES\.find\(\(s\) => s\.id === "nobodys-witness-film"\)/.test(appSrc), "the animatic dialog lists the shipped film's scenes, not a saved copy's (the exporter renders the shipped film)");
const exportServer = read("tools/vite-animatic-export.mjs");
check(/\.\.\.\(whole \? \[\] : \["--from"/.test(exportServer), "a whole-film export passes no --from: it starts where the film starts");
// a reload resumes the last checkpoint, which must never be a credits roll (the opening titles sent it past scenes 1 and 2)
{
  const mem = new Map<string, string>();
  (globalThis as unknown as { localStorage: Storage }).localStorage = { getItem: (k: string) => mem.get(k) ?? null, setItem: (k: string, v: string) => void mem.set(k, v), removeItem: (k: string) => void mem.delete(k), clear: () => mem.clear(), key: () => null, length: 0 } as Storage;
  const base = { storyId: FILM.id, sceneTitle: "", activeFlags: [], inventory: [], meters: {}, characterTrust: {}, memories: {}, proseAcknowledged: true, beatIdx: 0, usedHotspots: [], usedChoices: [], visitedScenes: [], encounteredCharacters: [], expiredChoices: [], choiceClocks: {} } as never;
  writeSave(0, { ...(base as object), sceneId: "nw_s2", savedAt: 1 } as never);
  writeSave(0, { ...(base as object), sceneId: "nw_title", savedAt: 2 } as never); // an older build's checkpoint on the opening titles
  eq(latestSave(FILM), null, "an automatic checkpoint on the opening titles is not offered for resume");
  writeSave(1, { ...(base as object), sceneId: "nw_title", savedAt: 3 } as never);
  eq(latestSave(FILM)?.slot, 1, "a manual save on a credits roll is the player's own choice and stays");
  mem.clear();
}
const gameSrc = read("src/game/Game.tsx");
check((gameSrc.match(/scene\.nodeType === "credits"/g) ?? []).length >= 2, "the player writes no automatic checkpoint on a credits roll (arrival or mid-scene)");

